#include "../../02-数据结构/莫队变体.cpp"
int main(){mt19937 r(97);for(int t=0;t<80;t++){int n=1+r()%40,s=1+r()%10;vector<int>a(n);for(int &x:a)x=r()%s;vector<Modification> changes;vector<TimedQuery> qs;vector<int> cur=a,want;vector<pair<int,int>> ranges;for(int k=0;k<200;k++){if(r()%3==0){int p=r()%n,v=r()%s;changes.push_back({p,cur[p],v});cur[p]=v;}else{int l=r()%n,h=r()%n;if(l>h)swap(l,h);qs.push_back({l,h,(int)changes.size()});ranges.push_back({l,h});want.push_back(set<int>(cur.begin()+l,cur.begin()+h+1).size());}}assert(modified_mo(a,s,changes,qs)==want);auto span=rollback_mo(a,s,ranges);for(int k=0;k<(int)ranges.size();k++){auto [l,h]=ranges[k];int z=0;for(int i=l;i<=h;i++)for(int j=i;j<=h;j++)if(a[i]==a[j])z=max(z,j-i);assert(span[k]==z);}vector<vector<int>> g(n);for(int i=1;i<n;i++){int p=r()%i;g[i].push_back(p);g[p].push_back(i);}auto ans=tree_mo(g,a,s,ranges);for(int k=0;k<(int)ranges.size();k++){auto [u,v]=ranges[k];vector<int> p(n,-1);queue<int>q;p[u]=u;q.push(u);while(!q.empty()){int x=q.front();q.pop();for(int y:g[x])if(p[y]<0)p[y]=x,q.push(y);}set<int> colors;for(int x=v;;x=p[x]){colors.insert(a[x]);if(x==u)break;}assert(ans[k]==(int)colors.size());}}}
